'use client';

import * as React from 'react';
import './row.css';

/* ROW: a row in a list.
 *   list     a compact row of a pinned query (5 / 8, radius 12, 13 pt); hover raises it
 *   panel    a row of a gathered panel (8 / 12, radius 14, 14 pt); hover raises it
 *   option   a palette row (36 tall, radius 12); the active one raises with a green rail
 * checked strikes the text in ink3; maybe fades a weak match. Slots: Row.Root, Row.Lead, Row.Text, Row.Trail. */

export interface RowRootProps extends React.HTMLAttributes<HTMLElement> {
  variant?: 'list' | 'panel' | 'option';
  checked?: boolean;
  /** option: the active row. */
  active?: boolean;
  /** a weak match, faded. */
  maybe?: boolean;
  as?: 'div' | 'li' | 'tr' | 'button';
}

const Root = React.forwardRef<HTMLElement, RowRootProps>(function RowRoot({ variant = 'list', checked, active, maybe, as = 'div', className, ...props }, ref) {
  const Tag = as as React.ElementType;
  return (
    <Tag
      ref={ref}
      data-variant={variant}
      data-checked={checked ? '' : undefined}
      data-active={active ? '' : undefined}
      data-maybe={maybe ? '' : undefined}
      className={className ? `mu-row ${className}` : 'mu-row'}
      {...props}
    />
  );
});
function Lead({ className, ...props }: React.HTMLAttributes<HTMLSpanElement>) {
  return <span className={className ? `mu-row-lead ${className}` : 'mu-row-lead'} {...props} />;
}
function Text({ className, ...props }: React.HTMLAttributes<HTMLSpanElement>) {
  return <span className={className ? `mu-row-text ${className}` : 'mu-row-text'} {...props} />;
}
function Trail({ className, ...props }: React.HTMLAttributes<HTMLSpanElement>) {
  return <span className={className ? `mu-row-trail ${className}` : 'mu-row-trail'} {...props} />;
}

export const Row = Object.assign(Root, { Root, Lead, Text, Trail });
export type RowProps = RowRootProps;

@import "../tokens.css";

/* Row: a row in a list. Its look is the row recipe (--mu-r-row-*). */
.mu-row {
  position: relative;
  box-sizing: border-box;
  display: flex;
  align-items: flex-start;
  color: var(--mu-ink);
  cursor: pointer;
  outline: var(--mu-zero);
  transition: background var(--mu-r-row-self-fade), box-shadow var(--mu-r-row-self-fade);
}
.mu-row[data-variant="list"] { gap: var(--mu-r-row-list-gap); padding: var(--mu-r-row-list-pad-y) var(--mu-r-row-list-pad-x); border-radius: var(--mu-r-row-list-radius); font: var(--mu-r-row-list-font); }
.mu-row[data-variant="list"]:is(:hover, :focus-visible) { background: var(--mu-r-row-list-hover-background); box-shadow: var(--mu-r-row-list-hover-shadow); }
.mu-row[data-variant="panel"] { gap: var(--mu-r-row-panel-gap); padding: var(--mu-r-row-panel-pad-y) var(--mu-r-row-panel-pad-x); border-radius: var(--mu-r-row-panel-radius); font: var(--mu-r-row-panel-font); }
.mu-row[data-variant="panel"]:is(:hover, :focus-visible) { background: var(--mu-r-row-panel-hover-background); box-shadow: var(--mu-r-row-panel-hover-shadow); }
.mu-row[data-variant="option"] { align-items: center; gap: var(--mu-r-row-option-gap); height: var(--mu-r-row-option-height); padding: var(--mu-zero) var(--mu-r-row-option-pad-x); border-radius: var(--mu-r-row-option-radius); font: var(--mu-r-row-option-font); transition: none; }
.mu-row[data-variant="option"] > svg, .mu-row[data-variant="option"] > .mu-row-lead > svg { width: var(--mu-r-row-option-glyph); height: var(--mu-r-row-option-glyph); color: var(--mu-ink2); flex: none; }
.mu-row[data-variant="option"]:is([data-active], [data-highlighted]) { background: var(--mu-r-row-option-on-background); box-shadow: var(--mu-r-row-option-on-shadow); }
.mu-row[data-variant="option"]:is([data-active], [data-highlighted])::before {
  content: "";
  position: absolute;
  left: var(--mu-r-row-rail-offset);
  top: var(--mu-r-row-rail-inset);
  bottom: var(--mu-r-row-rail-inset);
  width: var(--mu-r-row-rail-w);
  border-radius: var(--mu-r-row-rail-radius);
  background: var(--mu-r-row-rail-color);
}
.mu-row[data-maybe] { opacity: var(--mu-r-row-self-maybe); }
.mu-row-lead { display: inline-flex; flex: none; }
.mu-row-text { flex: 1; min-width: var(--mu-zero); }
.mu-row[data-checked] .mu-row-text { color: var(--mu-r-row-text-checked); text-decoration: line-through; }
.mu-row-trail { display: inline-flex; align-items: center; gap: var(--mu-r-row-option-gap); margin-left: auto; }
